import json


class FakeResponse:
    def __init__(self, status_code, body, headers=None):
        self.status_code = status_code
        self.body = body
        self.headers = headers or {}


busy = [429]                                   # page 2 answers 429 once


def fake_get(url):
    page = int(url.rsplit("=", 1)[1])
    if page == 2 and busy:
        busy.pop()
        return FakeResponse(429, {"error": "slow down"}, {"Retry-After": "2"})
    with open(f"schools_api_page{page}.json", encoding="utf-8") as f:
        return FakeResponse(200, json.load(f))


results = []
url = "https://api.example.org/schools?page=1"
while url:
    resp = fake_get(url)
    status = resp.status_code
    if status == 429:
        wait = float(resp.headers["Retry-After"])      # real code: sleep(wait)
        continue
    results.extend(r["id"] for r in resp.body["results"])
    url = resp.body["next"]
print(len(results), "schools")
